package main
import ("unsafe";"reflect";"math")
func tags() int {t:=reflect.TypeFor[struct{A int `k:"ab"`}](); return len(t.Field(0).Tag.Get("k"))}
func promoted() int {type Cell struct{N int};type Pair struct{Cell;Other Cell}; x:=Pair{Cell{2},Cell{5}};x.N++;return 10*x.N+x.Other.N}
func first() bool {a:=[2]byte{'x','x'}; s:=unsafe.String(&a[0],1);t:=unsafe.String(&a[1],1);return unsafe.StringData(min(t,s))==&a[1]}
func sign() bool {n:=math.Copysign(0,-1); return math.Signbit(min(0,n))}
func nan() bool {n:=math.NaN(); v:=max(1,n,2);return v!=v}
func quotient() int {x:=complex128(4+8i);y:=complex128(1+1i);z:=x/y;return int(10*real(z)+imag(z))}
func skip() int {var p *struct{A [3]byte};return len(p.A)}
func evaluate() int {c:=make(chan int,1);c<-0;a:=[1][3]byte{};n:=cap(a[<-c]);return 10*n+len(c)}
